import type { NationId, UnitClass, WorldState } from '@brink/contracts';
import { cellNeighbors, type MapFile, parseMap, terrainAt } from '@brink/map';
import { buildScenario, type ScenarioSetup } from './build';
import testbedMap from './maps/testbed.map.json' with { type: 'json' };

// The world-engine testbed (docs/mapgen.md): six powers and four minor states on a 64 x 32 map of
// synthetic continents, generated by packages/mapgen. Not a theatre a player picks (it is in neither
// SCENARIOS nor THEATRES); it keeps the engine, the AI and the builder honest about N powers on any
// size of map.

export const TESTBED_ID = 'testbed-six';

export const TESTBED_MAP: MapFile = parseMap(testbedMap, 'maps/testbed.map.json');

/** Every power with a coastal site puts a small navy to sea off the first one. */
function navies(map: MapFile): Record<NationId, { port: string; ships: UnitClass[] }> {
  const out: Record<NationId, { port: string; ships: UnitClass[] }> = {};
  for (const n of map.nations) {
    if (n.role !== 'power') continue;
    const port = map.sites.find((s) => s.owner === n.id && cellNeighbors(map, s.at).some(([c, r]) => terrainAt(map, c, r) === 'water'));
    if (port) out[n.id] = { port: port.name, ships: ['fleet', 'transport'] };
  }
  return out;
}

const SETUP: ScenarioSetup = { scenarioId: TESTBED_ID, maxTurns: 30, navies: navies(TESTBED_MAP) };

export function createTestbedScenario(seed: number): WorldState {
  return buildScenario(TESTBED_MAP, seed, SETUP);
}
